import { createRoute, z } from '@hono/zod-openapi'

const ChatRoleSchema = z
  .enum(['CHATBOT', 'SYSTEM', 'USER', 'TOOL'])
  .openapi({
    description:
      'One of `CHATBOT`, `SYSTEM`, `TOOL` or `USER` to identify who the message is coming from.\n',
    'x-fern-type-name': 'ChatRole',
  })
  .openapi('ChatRole')

const ToolCallSchema = z
  .object({
    name: z
      .string()
      .openapi({ 'x-fern-audiences': ['public'], description: 'Name of the tool to call.' }),
    parameters: z
      .looseObject({})
      .openapi({
        'x-fern-audiences': ['public'],
        description: 'The name and value of the parameters to use when invoking a tool.',
        'x-fern-type-name': 'ToolCall-iovxf2',
      }),
  })
  .openapi({
    description: 'Contains the tool calls generated by the model. Use it to invoke your tools.\n',
    required: ['name', 'parameters'],
    'x-fern-type-name': 'ToolCall',
  })
  .openapi('ToolCall')

const ChatMessageSchema = z
  .object({
    role: ChatRoleSchema.openapi({ 'x-fern-audiences': ['public'] }),
    message: z
      .string()
      .min(1)
      .openapi({ description: 'Contents of the chat message.\n', 'x-fern-audiences': ['public'] }),
    tool_calls: z
      .array(ToolCallSchema)
      .exactOptional()
      .openapi({ 'x-fern-audiences': ['public'] }),
  })
  .openapi({
    description:
      'Represents a single message in the chat history, excluding the current user turn. It has two properties: `role` and `message`. The `role` identifies the sender (`CHATBOT`, `SYSTEM`, or `USER`), while the `message` contains the text content.\n\nThe chat_history parameter should not be used for `SYSTEM` messages in most cases. Instead, to add a `SYSTEM` role message at the beginning of a conversation, the `preamble` parameter should be used.\n',
    required: ['role', 'message'],
    'x-fern-type-name': 'ChatMessage',
  })
  .openapi('ChatMessage')

const ToolResultSchema = z
  .object({
    call: ToolCallSchema,
    outputs: z.array(z.looseObject({}).openapi({ 'x-fern-type-name': 'ToolResult-68w0tx' })).min(0),
  })
  .openapi({ required: ['call', 'outputs'], 'x-fern-type-name': 'ToolResult' })
  .openapi('ToolResult')

const ChatToolMessageSchema = z
  .object({ role: ChatRoleSchema, tool_results: z.array(ToolResultSchema).exactOptional() })
  .openapi({
    description: 'Represents tool result in the chat history.\n',
    required: ['role'],
    'x-fern-type-name': 'ChatToolMessage',
  })
  .openapi('ChatToolMessage')

type MessageType = z.infer<typeof ChatMessageSchema> | z.infer<typeof ChatToolMessageSchema>

