export const postV1EmbedRoute = createRoute({
  method: 'post',
  path: '/v1/embed',
  summary: 'Embed API (v1)',
  description:
    'This endpoint returns text and image embeddings. An embedding is a list of floating point numbers that captures semantic information about the content that it represents.\n\nEmbeddings can be used to create classifiers as well as empower semantic search. To learn more about embeddings, see the embedding page.\n\nIf you want to learn more how to use the embedding model, have a look at the [Semantic Search Guide](https://docs.cohere.com/docs/semantic-search).',
  operationId: 'embed',
  request: {
    headers: z.object({ 'X-Client-Name': RequestSourceParamsSchema }),
    body: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              texts: z
                .array(z.string().openapi({ 'x-fern-audiences': ['public'], writeOnly: true }))
                .min(1)
                .max(96)
                .exactOptional()
                .openapi({
                  'x-fern-audiences': ['public'],
                  description:
                    'An array of strings for the model to embed. Maximum number of texts per call is `96`.',
                  writeOnly: true,
                }),
              images: z
                .array(z.string().openapi({ 'x-fern-audiences': ['public'], writeOnly: true }))
                .min(1)
                .exactOptional()
                .openapi({
                  'x-fern-audiences': ['public'],
                  description:
                    'An array of image data URIs for the model to embed.\n\nThe image must be a valid [data URI](https://developer.mozilla.org/en-US/docs/Web/URI/Schemes/data). The image must be in either `image/jpeg`, `image/png`, `image/webp`, or `image/gif` format.\n\nImage embeddings are supported with Embed v3.0 and newer models.\n\nFor **Embed v3.x** models, the maximum number of images per call is `1`, and each image has a maximum size of `5MB`.\n\nFor **Embed v4.0 and newer** models, there is no limit on the number of images per call. The combined size of all images in the request must be at most `20MB`.',
                }),
              model: z
                .string()
                .exactOptional()
                .openapi({
                  'x-fern-audiences': ['public'],
                  description:
                    'ID of one of the available [Embedding models](https://docs.cohere.com/docs/cohere-embed).',
                  writeOnly: true,
                }),
              input_type: EmbedInputTypeSchema.exactOptional().openapi({
                'x-fern-audiences': ['public'],
              }),
              embedding_types: z
                .array(EmbeddingTypeSchema)
                .exactOptional()
                .openapi({
                  'x-fern-audiences': ['public'],
                  description:
                    'Specifies the types of embeddings you want to get back. Not required and default is None, which returns the Embed Floats response type. Can be one or more of the following types.\n\n* `"float"`: Use this when you want to get back the default float embeddings. Supported with all Embed models.\n* `"int8"`: Use this when you want to get back signed int8 embeddings. Supported with Embed v3.0 and newer Embed models.\n* `"uint8"`: Use this when you want to get back unsigned int8 embeddings. Supported with Embed v3.0 and newer Embed models.\n* `"binary"`: Use this when you want to get back signed binary embeddings. Supported with Embed v3.0 and newer Embed models.\n* `"ubinary"`: Use this when you want to get back unsigned binary embeddings. Supported with Embed v3.0 and newer Embed models.',
                  writeOnly: true,
                }),
              truncate: z
                .enum(['NONE', 'START', 'END'])
                .default('END')
                .exactOptional()
                .openapi({
                  'x-fern-audiences': ['public'],
                  description:
                    'One of `NONE|START|END` to specify how the API will handle inputs longer than the maximum token length.\n\nPassing `START` will discard the start of the input. `END` will discard the end of the input. In both cases, input is discarded until the remaining input is exactly the maximum input token length for the model.\n\nIf `NONE` is selected, when the input exceeds the maximum input token length an error will be returned.',
                  writeOnly: true,
                }),
            })
            .openapi({
              'x-fern-audiences': ['public'],
              'x-fern-type-name': 'EmbedRequest',
              required: [],
            }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: z
            .xor([EmbedFloatsResponseSchema, EmbedByTypeResponseSchema])
            .openapi({
              discriminator: {
                propertyName: 'response_type',
                mapping: {
                  embeddings_floats: '#/components/schemas/EmbedFloatsResponse',
                  embeddings_by_type: '#/components/schemas/EmbedByTypeResponse',
                },
              },
            }),
        },
      },
      headers: z.object({ 'X-API-Warning': ApiWarningHeaderSchema }),
    },
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    422: UnprocessableEntityResponse,
    429: RateLimitResponse,
    498: InvalidTokenResponse,
    499: RequestCancelledResponse,
    500: InternalServerErrorResponse,
    501: NotImplementedResponse,
    503: ServiceUnavailableResponse,
    504: GatewayTimeoutResponse,
  },
})

