export const getV1DatasetsIdRoute = createRoute({
  method: 'get',
  path: '/v1/datasets/{id}',
  tags: ['/datasets'],
  summary: 'Get a Dataset',
  description:
    "Retrieve a dataset by ID. See ['Datasets'](https://docs.cohere.com/docs/datasets) for more information.",
  operationId: 'get-dataset',
  request: {
    params: z.object({
      id: z
        .string()
        .regex(/^(?!usage$).*$/)
        .openapi({
          param: {
            name: 'id',
            in: 'path',
            required: true,
            schema: { type: 'string', 'x-fern-audiences': ['public'], pattern: '^(?!usage$).*$' },
          },
          'x-fern-audiences': ['public'],
        }),
    }),
    headers: z.object({ 'X-Client-Name': RequestSourceParamsSchema }),
  },
  responses: {
    200: {
      description: 'A successful response.',
      content: {
        'application/json': {
          schema: z
            .object({ dataset: DatasetSchema })
            .openapi({
              'x-fern-audiences': ['public'],
              required: ['dataset'],
              'x-fern-type-name': 'DatasetsGetResponse',
            }),
        },
      },
    },
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    422: UnprocessableEntityResponse,
    429: RateLimitResponse,
    498: InvalidTokenResponse,
    499: RequestCancelledResponse,
    500: InternalServerErrorResponse,
    501: NotImplementedResponse,
    503: ServiceUnavailableResponse,
    504: GatewayTimeoutResponse,
  },
})

