export const postV1SummarizeRoute = createRoute({
  method: 'post',
  path: '/v1/summarize',
  summary: 'Summarize',
  description:
    '<Warning>\nThis API is marked as "Legacy" and is no longer maintained. Follow the [migration guide](https://docs.cohere.com/docs/migrating-from-cogenerate-to-cochat) to start using the Chat API.\n</Warning>\nGenerates a summary in English for a given text.\n',
  operationId: 'summarize',
  request: {
    headers: z.object({ 'X-Client-Name': RequestSourceParamsSchema }),
    body: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              text: z
                .string()
                .min(250)
                .max(50000)
                .openapi({
                  'x-fern-audiences': ['public'],
                  description:
                    'The text to generate a summary for. Can be up to 100,000 characters long. Currently the only supported language is English.',
                  writeOnly: true,
                }),
              length: z
                .enum(['short', 'medium', 'long'])
                .default('medium')
                .exactOptional()
                .openapi({
                  'x-fern-audiences': ['public'],
                  description:
                    'One of `short`, `medium`, `long`, or `auto` defaults to `auto`. Indicates the approximate length of the summary. If `auto` is selected, the best option will be picked based on the input text.',
                  writeOnly: true,
                }),
              format: z
                .enum(['paragraph', 'bullets'])
                .default('paragraph')
                .exactOptional()
                .openapi({
                  'x-fern-audiences': ['public'],
                  description:
                    'One of `paragraph`, `bullets`, or `auto`, defaults to `auto`. Indicates the style in which the summary will be delivered - in a free form paragraph or in bullet points. If `auto` is selected, the best option will be picked based on the input text.',
                  writeOnly: true,
                }),
              model: z
                .string()
                .exactOptional()
                .openapi({
                  'x-fern-audiences': ['public'],
                  description:
                    'The identifier of the model to generate the summary with. Currently available models are `command` (default), `command-nightly` (experimental), `command-light`, and `command-light-nightly` (experimental). Smaller, "light" models are faster, while larger models will perform better.',
                  writeOnly: true,
                }),
              extractiveness: z
                .enum(['low', 'medium', 'high'])
                .default('low')
                .exactOptional()
                .openapi({
                  'x-fern-audiences': ['public'],
                  description:
                    'One of `low`, `medium`, `high`, or `auto`, defaults to `auto`. Controls how close to the original text the summary is. `high` extractiveness summaries will lean towards reusing sentences verbatim, while `low` extractiveness summaries will tend to paraphrase more. If `auto` is selected, the best option will be picked based on the input text.',
                  writeOnly: true,
                }),
              temperature: z
                .number()
                .min(0)
                .max(5)
                .default(0.3)
                .exactOptional()
                .openapi({
                  'x-fern-audiences': ['public'],
                  description:
                    'Ranges from 0 to 5. Controls the randomness of the output. Lower values tend to generate more “predictable” output, while higher values tend to generate more “creative” output. The sweet spot is typically between 0 and 1.',
                  writeOnly: true,
                }),
              additional_command: z
                .string()
                .exactOptional()
                .openapi({
                  'x-fern-audiences': ['public'],
                  description:
                    'A free-form instruction for modifying how the summaries get generated. Should complete the sentence "Generate a summary _". Eg. "focusing on the next steps" or "written by Yoda"',
                  writeOnly: true,
                }),
            })
            .openapi({
              'x-fern-audiences': ['public'],
              required: ['text'],
              'x-fern-type-name': 'SummarizeRequest',
            }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: z
            .object({
              id: z
                .string()
                .exactOptional()
                .openapi({
                  'x-fern-audiences': ['public'],
                  description: 'Generated ID for the summary',
                }),
              summary: z
                .string()
                .exactOptional()
                .openapi({
                  'x-fern-audiences': ['public'],
                  description: 'Generated summary for the text',
                }),
              meta: ApiMetaSchema.exactOptional().openapi({ 'x-fern-audiences': ['public'] }),
            })
            .openapi({
              'x-fern-audiences': ['public'],
              'x-fern-type-name': 'SummarizeResponse',
              required: [],
            }),
        },
      },
      headers: z.object({ 'X-API-Warning': ApiWarningHeaderSchema }),
    },
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    422: UnprocessableEntityResponse,
    429: RateLimitResponse,
    498: InvalidTokenResponse,
    499: RequestCancelledResponse,
    500: InternalServerErrorResponse,
    501: NotImplementedResponse,
    503: ServiceUnavailableResponse,
    504: GatewayTimeoutResponse,
  },
  deprecated: true,
})

export const postV1TokenizeRoute = createRoute({
  method: 'post',
  path: '/v1/tokenize',
  summary: 'Tokenize',
  description:
    'This endpoint splits input text into smaller units called tokens using byte-pair encoding (BPE). To learn more about tokenization and byte pair encoding, see the tokens page.',
  operationId: 'tokenize',
  request: {
    headers: z.object({ 'X-Client-Name': RequestSourceParamsSchema }),
    body: {
      description: '',
      content: {
        'application/json': {
          schema: z
            .object({
              text: z
                .string()
                .min(1)
                .max(65536)
                .openapi({
                  'x-fern-audiences': ['public'],
                  description:
                    'The string to be tokenized, the minimum text length is 1 character, and the maximum text length is 65536 characters.',
                }),
              model: z
                .string()
                .openapi({
                  'x-fern-audiences': ['public'],
                  description:
                    'The input will be tokenized by the tokenizer that is used by this model.',
                }),
            })
            .openapi({
              'x-fern-audiences': ['public'],
              required: ['text', 'model'],
              'x-fern-type-name': 'TokenizeRequest',
            }),
          examples: { Example: { value: { text: 'tokenize me! :D', model: 'command' } } },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: z
            .object({
              tokens: z
                .array(z.int().openapi({ 'x-fern-audiences': ['public'] }))
                .openapi({
                  'x-fern-audiences': ['public'],
                  description: 'An array of tokens, where each token is an integer.',
                }),
              token_strings: z
                .array(z.string().openapi({ 'x-fern-audiences': ['public'] }))
                .openapi({ 'x-fern-audiences': ['public'] }),
              meta: ApiMetaSchema.exactOptional().openapi({ 'x-fern-audiences': ['public'] }),
            })
            .openapi({
              'x-fern-audiences': ['public'],
              required: ['tokens', 'token_strings'],
              'x-fern-type-name': 'TokenizeResponse',
            }),
          examples: {
            Example: {
              value: {
                tokens: [34160, 974, 514, 34, 1420, 69],
                token_strings: ['token', "ize'", ' me', '!', ' :', 'D'],
                meta: { api_version: { version: '1' } },
              },
            },
          },
        },
      },
      headers: z.object({ 'X-API-Warning': ApiWarningHeaderSchema }),
    },
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    422: UnprocessableEntityResponse,
    429: RateLimitResponse,
    498: InvalidTokenResponse,
    499: RequestCancelledResponse,
    500: InternalServerErrorResponse,
    501: NotImplementedResponse,
    503: ServiceUnavailableResponse,
    504: GatewayTimeoutResponse,
  },
})

