export const getV1ConnectorsRoute = createRoute({
  method: 'get',
  path: '/v1/connectors',
  tags: ['/connectors'],
  summary: 'List Connectors',
  description:
    "Returns a list of connectors ordered by descending creation date (newer first). See ['Managing your Connector'](https://docs.cohere.com/docs/managing-your-connector) for more information.",
  operationId: 'list-connectors',
  request: {
    query: z.object({
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number(),
        )
        .default(30)
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            description: 'Maximum number of connectors to return [0, 100].',
            schema: { default: 30, type: 'number', 'x-fern-audiences': ['public'] },
            required: false,
          },
          'x-fern-audiences': ['public'],
        }),
      offset: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.number(),
        )
        .default(0)
        .exactOptional()
        .openapi({
          param: {
            name: 'offset',
            in: 'query',
            description: 'Number of connectors to skip before returning results [0, inf].',
            schema: { default: 0, type: 'number', 'x-fern-audiences': ['public'] },
            required: false,
          },
          'x-fern-audiences': ['public'],
        }),
    }),
    headers: z.object({ 'X-Client-Name': RequestSourceParamsSchema }),
  },
  responses: {
    200: {
      description: 'OK',
      content: { 'application/json': { schema: ListConnectorsResponseSchema } },
    },
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    403: ForbiddenResponse,
    404: NotFoundResponse,
    422: UnprocessableEntityResponse,
    429: RateLimitResponse,
    498: InvalidTokenResponse,
    499: RequestCancelledResponse,
    500: InternalServerErrorResponse,
    501: NotImplementedResponse,
    503: ServiceUnavailableResponse,
    504: GatewayTimeoutResponse,
  },
  deprecated: true,
})

